     * @returns {string} The logout URL
     *
     * @example
     * const scalekit = new Scalekit(envUrl, clientId, clientSecret);
     * const logoutUrl = scalekit.getLogoutUrl({
     *   postLogoutRedirectUri: 'https://example.com',
     *   state: 'some-state'
     * });
